import {getFlow} from './model.mjs';
const key=p=>p.join('/');
export function openTab(tabs,path,ancestors=true){for(let i=ancestors?0:path.length;i<=path.length;i++){const p=path.slice(0,i);if(!tabs.some(t=>key(t.path)===key(p)))tabs.push({path:p,view:null});}return tabs;}
export function closeTab(tabs,path,active){if(!path.length)return active;const index=tabs.findIndex(t=>key(t.path)===key(path));if(index>=0)tabs.splice(index,1);if(key(active)!==key(path))return active;const parent=path.slice(0,-1);openTab(tabs,parent);return parent;}
export function restoreTabs(root,saved){const result=[{path:[],view:null}];for(const entry of Array.isArray(saved)?saved.slice(0,301):[]){const p=entry?.path;if(!Array.isArray(p)||p.length>20||!p.every(id=>typeof id==='string')||!getFlow(root,p))continue;const existing=result.find(t=>key(t.path)===key(p));if(existing?.view)continue;openTab(result,p,false);const tab=result.find(t=>key(t.path)===key(p)),v=entry.view;if(v&&Number.isFinite(v.zoom)&&v.zoom>=.3&&v.zoom<=2&&Number.isFinite(v.hzoom)&&v.hzoom>=.2&&v.hzoom<=4&&Number.isFinite(v.left)&&v.left>=0&&Number.isFinite(v.top)&&v.top>=0)tab.view={zoom:v.zoom,hzoom:v.hzoom,left:v.left,top:v.top};}return result;}
